insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020000','Verifique o conceito','O que uma rede local conecta?','["Dispositivos de uma área","Todos os sites do mundo","Somente monitores"]'::jsonb,'Dispositivos de uma área. Wi-Fi é uma forma de ligação sem fio até um equipamento local. Um aparelho pode mostrar Wi-Fi conectado mesmo quando o acesso externo está indisponível.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020000',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020001','Verifique o conceito','Wi-Fi conectado garante internet?','["Não","Sim","Somente com DNS"]'::jsonb,'Não. Internet interliga várias redes. O roteador encaminha pacotes, pequenas partes de dados, de uma rede para outra conforme o destino.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020001',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020002','Verifique o conceito','O que um roteador encaminha?','["Pacotes entre redes","Títulos HTML","Baterias"]'::jsonb,'Pacotes entre redes. Uma página é procurada por nome. DNS é o serviço que relaciona o nome de domínio a um endereço IP, identificação usada para localizar o destino na rede.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020002',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020003','Verifique o conceito','Qual serviço relaciona nome e IP?','["DNS","CSS","Bluetooth"]'::jsonb,'DNS. Separe as observações: há ligação à rede local? Há acesso externo por endereço? Um nome de site é resolvido? Cada resposta aponta para uma etapa diferente.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020003',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020004','Verifique o conceito','O que identifica uma interface na rede?','["Endereço IP","Título da página","Rótulo do formulário"]'::jsonb,'Endereço IP. DNS consulta a relação entre um nome, como um domínio escolar, e o endereço IP usado para chegar ao destino. Resolver o nome é uma etapa distinta de manter o enlace local.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020004',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020005','Verifique o conceito','Qual tarefa cabe ao DNS?','["Resolver nome para endereço","Trocar um cabo","Desenhar uma página"]'::jsonb,'Resolver nome para endereço. O roteador encaminha pacotes para outras redes. Se o aparelho alcança o roteador, isso confirma parte do caminho local, não todas as etapas externas.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020005',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020006','Verifique o conceito','O que um roteador faz?','["Encaminha pacotes entre redes","Converte palavras em imagens","Valida o conteúdo do site"]'::jsonb,'Encaminha pacotes entre redes. HTTPS indica comunicação Web protegida por criptografia entre navegador e servidor, com verificação de identidade do servidor; não significa que todo conteúdo de uma página seja confiável.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020006',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020007','Verifique o conceito','HTTPS protege que trecho?','["Comunicação entre navegador e servidor","Todas as decisões do usuário","O monitor do computador"]'::jsonb,'Comunicação entre navegador e servidor. Em um relato de falha, identifique o que foi testado: acesso ao roteador, acesso a um IP externo e acesso pelo nome. Não atribua toda falha ao DNS sem evidência.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020007',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020008','Verifique o conceito','O que registrar primeiro?','["O que funciona e o que falha","Uma peça para trocar","A conclusão antes do teste"]'::jsonb,'O que funciona e o que falha. Confira o enlace local: o dispositivo está conectado ao Wi-Fi e alcança o roteador? O ícone de Wi-Fi sozinho não comprova acesso à internet.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020008',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020009','Verifique o conceito','Wi-Fi conectado comprova internet?','["Não","Sim","Comprova o DNS"]'::jsonb,'Não. Depois confira acesso externo por endereço IP conhecido e autorizado para o teste. Se não funcionar, investigue o caminho externo antes de culpar nomes de sites.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020009',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020010','Verifique o conceito','IP externo funciona, nome falha: investigar o quê?','["DNS","Cor do monitor","Teclado"]'::jsonb,'DNS. Se o acesso externo por IP funciona, mas por nome não, teste configuração e resposta do DNS. A diferença entre os dois testes é a evidência relevante.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020010',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020011','Verifique o conceito','Após uma mudança, o que fazer?','["Repetir o teste e comparar","Apagar o registro","Trocar tudo"]'::jsonb,'Repetir o teste e comparar. Registre horário, teste, resultado e próxima hipótese. Repita o mesmo teste após uma mudança para verificar se ela corrigiu a falha.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020011',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020012','Verifique o conceito','O que caracteriza uma estrela?','["Enlaces individuais ao centro","Um único cabo em linha","Nenhum equipamento central"]'::jsonb,'Enlaces individuais ao centro. Um switch conecta equipamentos na rede local. Ele encaminha tráfego entre portas conforme os endereços observados; cada cabo do desenho corresponde a um enlace.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020012',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020013','Verifique o conceito','Qual é o papel do switch?','["Ligar equipamentos da rede local","Medir corrente elétrica","Resolver nomes em todos os casos"]'::jsonb,'Ligar equipamentos da rede local. No diagrama da prática, o cabo X liga somente o computador B ao switch. Se apenas X for retirado, B perde esse enlace; A mantém o seu cabo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020013',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020014','Verifique o conceito','Se só o cabo B falha, quem perde esse enlace?','["B","Todos","A apenas"]'::jsonb,'B. Se o equipamento central falha, vários computadores ligados a ele podem perder a comunicação. Essa situação difere de desligar um cabo periférico.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020014',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020015','Verifique o conceito','O que pode afetar vários enlaces?','["Falha do equipamento central","Falha de um único cabo periférico","Mudança de título"]'::jsonb,'Falha do equipamento central. Para prever o impacto, siga o caminho de cada computador até o centro e marque exatamente o trecho interrompido.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020015',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020016','Verifique o conceito','Alcançar o roteador confirma o quê?','["Trecho local até ele","Todo site","Resolução DNS"]'::jsonb,'Trecho local até ele. Se o computador alcança o roteador, há comunicação local até ele no momento do teste. Isso não comprova o caminho até um servidor externo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020016',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020017','Verifique o conceito','Alcançar IP externo confirma o quê?','["Caminho externo daquele teste","Todos os nomes","Todas as páginas seguras"]'::jsonb,'Caminho externo daquele teste. Se um servidor externo responde por IP, o caminho externo funciona para aquele teste. Quando o mesmo destino não abre pelo nome, o DNS torna-se a hipótese principal.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020017',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020018','Verifique o conceito','IP funciona e nome falha: hipótese principal?','["DNS","Monitor","Bateria"]'::jsonb,'DNS. Verifique o endereço do servidor DNS configurado e sua resposta. Não conclua que todo cabo ou todo acesso externo está quebrado quando os testes por IP funcionam.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020018',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020019','Verifique o conceito','Por que mudar um fator por vez?','["Para relacionar mudança e resultado","Para evitar registro","Para pular testes"]'::jsonb,'Para relacionar mudança e resultado. Documente a sequência e a evidência que levou à hipótese; mude um fator de cada vez e repita o teste afetado.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000017',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020019',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020020','Verifique o conceito','Qual unidade mede tensão?','["Volt (V)","Ampere (A)","Ohm (Ω)"]'::jsonb,'Volt (V). Corrente é o fluxo de carga elétrica; mede-se em amperes (A). O valor da corrente depende do circuito fechado e de seus componentes.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020020',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020021','Verifique o conceito','Qual unidade mede corrente?','["Ampere (A)","Volt (V)","Metro (m)"]'::jsonb,'Ampere (A). Resistência oferece oposição à corrente; mede-se em ohms (Ω). Um resistor é um componente que pode limitar a corrente em um circuito.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020021',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020022','Verifique o conceito','Qual unidade mede resistência?','["Ohm (Ω)","Ampere (A)","Segundo (s)"]'::jsonb,'Ohm (Ω). Compare as unidades: V para tensão, A para corrente e Ω para resistência. Elas descrevem grandezas diferentes e não devem ser trocadas.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020022',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020023','Verifique o conceito','Que componente pode limitar corrente?','["Resistor","Fio ideal","Conector"]'::jsonb,'Resistor. Por enquanto, desenhe e simule somente circuitos de baixa tensão. Não ligue componentes de estudo diretamente à rede elétrica.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020023',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020024','Verifique o conceito','Qual é a relação da lei de Ohm?','["I = V / R","I = V + R","I = R / V"]'::jsonb,'I = V / R. A lei de Ohm relaciona tensão V, corrente I e resistência R: I = V / R. A divisão usa volts e ohms e resulta em amperes.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020024',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020025','Verifique o conceito','Quanto é 2 V / 100 Ω?','["0,02 A","2 A","200 A"]'::jsonb,'0,02 A. Para 2 V em um resistor de 100 Ω, I = 2 / 100 = 0,02 A, ou 20 mA. Um miliampere (mA) é um milésimo de ampere.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020025',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020026','Verifique o conceito','Quanto é 0,01 A em mA?','["10 mA","1 mA","100 mA"]'::jsonb,'10 mA. Com os mesmos 2 V e 200 Ω, I = 2 / 200 = 0,01 A, ou 10 mA. Dobrar a resistência reduz a corrente calculada à metade nesse modelo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020026',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020027','Verifique o conceito','Com tensão fixa, dobrar R faz I:','["Cair à metade","Dobrar","Ficar sempre igual"]'::jsonb,'Cair à metade. O cálculo idealizado não substitui conferir limites da fonte e do componente. Use o exercício em desenho ou simulador de baixa tensão, sem rede elétrica.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020027',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020028','Verifique o conceito','Qual é a função do resistor em série?','["Limitar corrente","Trocar a cor","Substituir a fonte"]'::jsonb,'Limitar corrente. Um LED tem polaridade: ânodo e cátodo indicam os lados. No desenho simplificado, a corrente convencional segue da saída positiva da fonte, pelo resistor e LED orientado, até o retorno.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020028',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020029','Verifique o conceito','Por que marcar ânodo e cátodo?','["Para orientar o LED","Para medir comprimento","Para escolher o nome"]'::jsonb,'Para orientar o LED. O resistor limita a corrente. Antes de uma montagem física, seria necessário consultar a especificação do LED, da fonte e do resistor; apenas a cor do LED não determina esses valores.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020029',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020030','Verifique o conceito','O que consultar antes de montar?','["Especificações dos componentes","Só a cor do LED","A velocidade da internet"]'::jsonb,'Especificações dos componentes. No simulador ou papel, observe o que muda ao inverter o LED: ele normalmente deixa de conduzir no sentido contrário dentro dos limites especificados.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020030',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000020031','Verifique o conceito','Qual ambiente usar nesta atividade?','["Papel ou simulação de baixa tensão","Tomada da rede elétrica","Ligação direta sem resistor"]'::jsonb,'Papel ou simulação de baixa tensão. Registre a orientação, a função do resistor e uma verificação de baixa tensão. Não use a rede elétrica nesta atividade.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000016',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000020031',0,'0'::jsonb) on conflict(question_id) do nothing;
